const issuedLabel=x=>x&&x.dateApprox&&x.issued?new Date(x.issued.slice(0,7)+'-15T12:00:00Z').toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'})+' (approx.)':date(x&&x.issued);
const opt=(value,label,selected)=>'<option value="'+e(value)+'"'+(value===selected?' selected':'')+'>'+e(label)+'</option>';
const input=(label,name,value='',type='text',extra='')=>'<label>'+e(label)+'<input name="'+e(name)+'" type="'+type+'" value="'+e(value)+'" '+extra+'></label>';
const action=(name,label,id='',kind='')=>'<button type="button" data-action="'+name+'" data-id="'+e(id)+'" class="'+kind+'">'+e(label)+'</button>';
const native=source=>!['report','portal'].includes(source.mode);
function clearWorkspace(){s.me=null;s.admin=null;s.csrf='';s.chosen=null;s.modal=null;s.upload=null;s.tab='radar';s.poll=false;s.saved=false;}
function notice(text,error=false){const t=$('#toast');t.textContent=text;t.className=error?'show error':'show';clearTimeout(notice.timer);notice.timer=setTimeout(()=>t.className='',error?12000:7000);}
async function api(path,body,method=body?'POST':'GET'){
 const res=await fetch(path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json','X-CSRF-Token':s.csrf||''}:{},body:body?JSON.stringify(body):undefined});const j=await res.json();
 if(!res.ok){if(res.status===401&&path!=='/api/login'){clearWorkspace();render();}throw new Error(j.error||'Falha na operação.');}return j;
}
function query(extra={}){const p=new URLSearchParams({...s.filters,...extra,cities:s.filters.cities.join(',')});return p.toString();}
async function radar(){s.radar=await api('/api/radar?'+query());s.sources=s.radar.sources;}
async function refresh(){if(s.tab==='radar'||s.tab==='coverage')await radar();render();}
async function uploadFile(u,confirm){
 const q=new URLSearchParams({sourceId:u.sourceId,month:u.month,to:u.toMonth&&u.toMonth>u.month?u.toMonth:u.month,filename:u.file.name,confirm:confirm?'1':'0'});
 const res=await fetch('/api/import-file?'+q,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream','X-CSRF-Token':s.csrf||''},body:u.file});
 const j=await res.json();if(!res.ok)throw new Error(j.error||'File import failed.');return j;
}
