 if(sec==='clients')body=clientsSection(d,cities,ed);
 if(sec==='coverage')body='<section class="panel"><p class="muted">Cities and trades each affiliated company can see, from its active client accounts.</p><div class="table-scroll"><table><thead><tr><th>Company</th><th>Trades</th><th>Cities</th></tr></thead><tbody>'+d.coverage.map(x=>'<tr><td>'+e(x.name)+(x.active?'':' <small>(inactive)</small>')+'</td><td>'+e(x.trades.join(', ')||'—')+'</td><td>'+e(x.cities.map(cityName).join(', ')||'No cities assigned')+'</td></tr>').join('')+'</tbody></table></div>'+(d.coverage.length?'':'<p class="empty">No affiliated companies yet.</p>')+'</section>';
 if(sec==='freshness'){const stale=d.freshness.filter(x=>x.stale).length;body='<section class="panel"><p class="'+(stale?'warning':'muted')+'">'+(stale?stale+' cities have no permits in the last '+d.settings.stale_days+' days (or none at all).':'All cities have recent permits.')+'</p><div class="table-scroll"><table><thead><tr><th>City</th><th>Permits</th><th>Last permit</th><th>Last collection</th><th>Days</th><th>Alert</th></tr></thead><tbody>'+d.freshness.map(x=>'<tr><td>'+e(x.city)+', '+x.state+'</td><td>'+x.permits+'</td><td>'+e(x.lastPermit||'—')+'</td><td>'+(x.lastCollection?date(x.lastCollection):'—')+'</td><td>'+(x.daysSincePermit===null?'—':x.daysSincePermit)+'</td><td>'+(x.stale?'<span class="badge review">'+(x.permits?'Stale':'No data')+'</span>':'OK')+'</td></tr>').join('')+'</tbody></table></div></section>';}
 if(sec==='retention'){const r=d.retention;body='<section class="panel"><p>Permits issued more than <b>'+r.months+' months</b> ago are deleted every day (by issue date).</p><p>Last run: '+(r.last?e(r.last.day)+' · '+r.last.deleted+' deleted (before '+e(r.last.cutoff)+')':'never')+' · Total deleted: <b>'+r.totalDeleted+'</b></p></section>';}
 if(sec==='audit')body='<section class="panel"><div class="table-scroll"><table><thead><tr><th>When</th><th>Who</th><th>Type</th><th>What</th></tr></thead><tbody>'+d.audit.map(x=>'<tr><td>'+date(x.createdAt)+'</td><td>'+e(x.actor||'system')+'</td><td>'+e(x.kind)+'</td><td>'+e(x.event)+'</td></tr>').join('')+'</tbody></table></div>'+(d.audit.length?'':'<p class="empty">Nothing recorded yet.</p>')+'</section>';
 if(sec==='usage')body='<section class="panel"><p class="muted">Permits seen and exported by each affiliated company (filled once the client area exists).</p><div class="table-scroll"><table><thead><tr><th>Company</th><th>Permits seen</th><th>Permits exported</th><th>Last activity</th></tr></thead><tbody>'+d.usage.map(x=>'<tr><td>'+e(x.name)+'</td><td>'+x.seen+'</td><td>'+x.exported+'</td><td>'+(x.lastAt?date(x.lastAt):'—')+'</td></tr>').join('')+'</tbody></table></div>'+(d.usage.length?'':'<p class="empty">No affiliated companies yet.</p>')+'</section>';
 if(sec==='psettings')body='<form class="panel settings-panel" data-form="pset"><h2>System settings</h2><div class="form-grid">'+input('Retention (months)','retention_months',d.settings.retention_months,'number','required min="1" max="120"')+input('Alert after days without permits','stale_days',d.settings.stale_days,'number','required min="1" max="365"')+input('E-mail for alerts (failed cities, old data)','alert_email',d.automation?.alertEmail||'','email')+'</div><label class="archive-toggle"><input type="checkbox" name="client_portal" value="1" '+(d.settings.client_portal?'checked':'')+'> Client channel enabled (clients sign in at their own endpoint and never receive municipal links)</label><button class="primary" type="submit">Save settings</button></form>'+automationPanel(d.automation);
