function cleanDesc(text){
 const raw=String(text||'').replace(/\s+/g,' ').trim(),parts=raw.split(/\s+[—–]\s+/);
 if(parts.length<2)return raw;
 const words=x=>x.toLowerCase().match(/[a-z0-9]{4,}/g)||[],head=new Set(words(parts[0])),tail=words(parts.slice(1).join(' '));
 return tail.length&&tail.filter(w=>head.has(w)).length/tail.length>=.6?parts[0]:raw;
}
function splitPerson(v){const x=String(v||'').split(/\s*[•|]\s*/),company=x.find(y=>/^(empresa associada|company)\s*:/i.test(y)),name=x.filter(y=>y!==company).join(' ').trim();return {name,company:company?company.replace(/^[^:]+:\s*/,'').trim():''};}
const field=(label,value,html)=>'<div class="kv"><small>'+label+'</small><b>'+(value?(html||e(value)):'<span class="muted">Not available</span>')+'</b></div>';
function automationPanel(a){
 if(!a)return '';
 const line=(label,v)=>'<div class="kv"><small>'+label+'</small><b>'+v+'</b></div>',b=a.backup,al=a.alert,r=a.report;
 return '<section class="panel"><h2>Automation</h2><div class="kv-grid">'+line('Daily collection','Every day after 8:00 (New York time)')+line('Last backup',b.day?e(b.day)+' · '+e(String(b.detail).split('/').pop()):'Not yet (runs daily after 10:00)')+line('Last daily check',r?e(r.day)+' · '+r.failing+' failing, '+r.stale+' with old data':'Not yet')+line('Alert e-mail',a.alertEmail?e(a.alertEmail):'Not set')+line('Mail server',a.mailConfigured?'Configured':'<span class="muted">Not configured — alerts show only here</span>')+line('Last alert',al.day?e(al.day)+' · '+e(al.detail):'None sent')+'</div>'+(a.alertEmail?'<div class="actions">'+action('testEmail','Send test e-mail')+'</div>':'')+'</section>';
}
